#!/usr/bin/env node
// Fill firebase-config.js from environment variables, for hosts that build.
//
//   npm run config        # locally
//   (Netlify runs this as the build command)
//
// Behaviour:
//   · no FIREBASE_* variables set  → leave the committed file alone, exit 0
//   · all six set                  → rewrite firebase-config.js, exit 0
//   · only some set                → exit 1 and name the missing ones
//
// The generated file is served to the browser, so this tidies the repository and
// lets environments differ — it does not make the values secret.

import fs from 'node:fs';
import path from 'node:path';

export const FIELDS = [
  ['apiKey', 'FIREBASE_API_KEY'],
  ['authDomain', 'FIREBASE_AUTH_DOMAIN'],
  ['projectId', 'FIREBASE_PROJECT_ID'],
  ['storageBucket', 'FIREBASE_STORAGE_BUCKET'],
  ['messagingSenderId', 'FIREBASE_MESSAGING_SENDER_ID'],
  ['appId', 'FIREBASE_APP_ID']
];

const HEADER = `// GENERATED by scripts/generate-config.mjs from environment variables.
// Do not edit by hand — change the FIREBASE_* variables and rebuild.
// These values are public: they are served to the browser either way.

`;

/** Build the file body for a set of values. */
export function renderConfig(values) {
  const lines = FIELDS.map(([key]) => `  ${key}: ${JSON.stringify(values[key])}`);
  return `${HEADER}export const FIREBASE_CONFIG = {\n${lines.join(',\n')}\n};\n`;
}

/** Read the six variables out of an env object. */
export function readEnv(env = process.env) {
  const values = {};
  const missing = [];
  for (const [key, name] of FIELDS) {
    const raw = (env[name] || '').trim();
    if (raw) values[key] = raw;
    else missing.push(name);
  }
  return { values, missing };
}

function main() {
  const root = path.resolve(path.dirname(new URL(import.meta.url).pathname), '..');
  const target = path.join(root, 'firebase-config.js');

  const { values, missing } = readEnv();

  if (missing.length === FIELDS.length) {
    console.log('No FIREBASE_* environment variables set — leaving firebase-config.js as committed.');
    return 0;
  }

  if (missing.length) {
    console.error(`Missing ${missing.length} of ${FIELDS.length} Firebase variables:`);
    for (const name of missing) console.error(`  · ${name}`);
    console.error('Set all of them, or none of them, then run this again.');
    return 1;
  }

  fs.writeFileSync(target, renderConfig(values), 'utf8');
  console.log(`Wrote firebase-config.js for project "${values.projectId}".`);
  return 0;
}

// only run when executed directly, so the test suite can import the helpers
const invokedDirectly = process.argv[1] && process.argv[1].endsWith('generate-config.mjs');
if (invokedDirectly) {
  process.exit(main());
}
